export async function upsertContact(input: IncomingContact, tx: Tx) {
  // Normalise before comparing, or Ali@Example.COM and ali@example.com become
  // two people and stay that way.
  const email = input.email.trim().toLowerCase();

  const exact = await tx.query.contacts.findFirst({
    where: eq(contacts.emailNormalised, email),
  });
  if (exact) return applyUpdate(exact, input, tx);

  // Weaker signal: same name at the same company. Real often enough to flag,
  // wrong often enough that merging on it silently destroys data.
  const probable = await tx.query.contacts.findFirst({
    where: and(
      eq(contacts.fullNameNormalised, normaliseName(input.fullName)),
      eq(contacts.accountId, input.accountId),
    ),
  });
  if (probable) {
    await tx.insert(mergeCandidates).values({
      existingId: probable.id,
      incoming: input,
      reason: 'name_and_account',
    });
    // Created separately and queued for a human. Never merged on a guess.
    return createContact(input, tx);
  }

  return createContact(input, tx);
}

export async function merge(keepId: string, mergeId: string, tx: Tx) {
  // Activity moves first. It is usually the reason the duplicate mattered.
  await tx.update(activities).set({ contactId: keepId })
    .where(eq(activities.contactId, mergeId));
  await tx.update(deals).set({ contactId: keepId })
    .where(eq(deals.contactId, mergeId));

  // Tombstone rather than delete: old links, reports and integrations still
  // reference the merged id and should resolve, not 404.
  await tx.update(contacts)
    .set({ mergedIntoId: keepId, mergedAt: new Date() })
    .where(eq(contacts.id, mergeId));
}
